export declare const chromeStyles = "\n/* ---- \u5DE5\u4F5C\u53F0\u9AA8\u67B6\uFF1A\u6839\u5BB9\u5668\u4E0E\u5168\u5C40\u5B57\u4F53 ---- */\n.wf-root {\n  position: relative;\n  inset: auto;\n  width: 100%;\n  height: 100%;\n  max-height: 100vh;\n  min-height: 0;\n  display: grid;\n  grid-template-rows: 48px minmax(0, 1fr) auto;\n  background: var(--wf-bg);\n  color: var(--wf-ink);\n  font: 13px/1.5 ui-sans-serif, system-ui, -apple-system, \"Segoe UI\", sans-serif;\n  overflow: hidden;\n}\n\n.wf-root * {\n  box-sizing: border-box;\n}\n\n.wf-root button,\n.wf-root input,\n.wf-root select,\n.wf-root textarea {\n  font: inherit;\n}\n\n.wf-root button {\n  cursor: pointer;\n}\n\n/* ---- \u9876\u680F\u6807\u7B7E\u680F\uFF08\u6807\u9898 / \u5FBD\u6807 / \u8BF4\u660E\uFF09 ---- */\n.wf-tabs {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 0 20px;\n  background: var(--wf-layer);\n  border-bottom: 1px solid var(--wf-border);\n  flex: none;\n  min-width: 0;\n}\n\n.wf-titlebar__title {\n  font-size: 14px;\n  font-weight: 720;\n  color: var(--wf-ink);\n  white-space: nowrap;\n}\n\n.wf-titlebar__badge {\n  padding: 3px 7px;\n  border-radius: 999px;\n  background: color-mix(in srgb, var(--wf-brand) 10%, transparent);\n  color: var(--wf-brand);\n  font-size: 10px;\n  font-weight: 700;\n  white-space: nowrap;\n}\n\n.wf-titlebar__note {\n  color: var(--wf-ink-2);\n  font-size: 11px;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.wf-titlebar__spacer {\n  margin-left: auto;\n  flex: 1;\n}\n\n.wf-titlebar__mode {\n  position: relative;\n  flex: none;\n}\n\n.wf-titlebar__caret {\n  margin-left: 4px;\n  font-size: 9px;\n  color: var(--wf-ink-2);\n}\n\n/* ---- \u9876\u680F\u6A21\u5F0F\u83DC\u5355 ---- */\n.wf-mode-menu {\n  position: absolute;\n  z-index: 60;\n  right: 0;\n  top: calc(100% + 6px);\n  min-width: 170px;\n  padding: 6px;\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 10px;\n  background: var(--wf-layer);\n  box-shadow: 0 14px 34px color-mix(in srgb, var(--wf-ink) 22%, transparent);\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n\n.wf-mode-menu__item {\n  text-align: left;\n  border: 0;\n  border-radius: 7px;\n  background: transparent;\n  color: var(--wf-ink);\n  padding: 7px 10px;\n  font-size: 12px;\n}\n\n.wf-mode-menu__item:hover {\n  background: color-mix(in srgb, var(--wf-brand) 10%, var(--wf-layer));\n  color: var(--wf-brand);\n}\n\n/* ---- \u4E3B\u533A\u5BB9\u5668\uFF08\u5DE6\u53F3\u680F + \u753B\u5E03\uFF09 ---- */\n.wf-main {\n  min-height: 0;\n  min-width: 0;\n  overflow: hidden;\n  display: flex;\n}\n";
